/* @layer shared-asset-extraction @kind logic */
import type { Headers } from '../c-parse/headers';
import { compiledIn, runtimeDefines } from './storage-defines';
import { checkLines, descLines, pointerLines } from './storage-tables';

const BASE_HEADER = 'battle_anim.h';

const DOC =
  '/* GENERATED by tools/gen/pack_tables.py headers -- do not edit. No data: the storage of every table,\n' +
  '   compiled only by a data-free build (CT_DATAFREE); src/datapack.c fills it from the pack made from\n' +
  '   your ROM (docs/ROM.md). */';

const DEFINES_DOC =
  "/* The #defines: a compiled-in one (an array bound) with the shapes' value, which the loader compares with\n" +
  "   the pack's; a run-time one with its variable, which the loader fills from the pack. */";

const defineLines = (hs: Headers): string[] => {
  const defines = hs.numericDefines();
  const keep = compiledIn(hs, defines);
  const kinds = new Map(runtimeDefines(hs, defines).map((d) => [d.name, d.ctype]));
  const lines = defines.map(({ name }) =>
    keep.has(name)
      ? `  { "${name}", (long long)(${name}), NULL, 0 },`
      : `  { "${name}", 0, &ctDef_${name}, ${kinds.get(name) === 'int' ? 'CT_TBL_DEF_INT' : 'CT_TBL_DEF_UINT'} },`,
  );
  return [DEFINES_DOC, 'const CtTableDefine ctTableDefines[] = {', ...lines, '};'];
};

/**
 * pack_tables.py make_headers(), the tables_storage.c part: every table defined once (zeroed; the pack fills it),
 * the layout model asserted against the compiler, the registry. The sizes, offsets, hashes and pointer offsets
 * come from the layout the headers were parsed with, so the pointer width is the headers' target (8 or 4 bytes).
 */
const writeTablesStorage = (hs: Headers): string => {
  const order = [...hs.texts.keys()].sort((a, b) => Number(a !== BASE_HEADER) - Number(b !== BASE_HEADER));
  const lines = [
    DOC,
    '#ifndef CT_DATAFREE\n#error "tables_storage.c is compiled only by a data-free build (CT_DATAFREE)"\n#endif',
    '#define CT_TBL_STORAGE',
    '#define CT_TBL_EXTERN',
    '#define CT_TBL_CONST',
    '#include <stddef.h>',
    ...order.map((h) => `#include "${h}"`),
    '#include "../datapack.h"',
    '',
    '/* The layout model of tools/gen/pack_tables.py, checked against this compiler. */',
    '#define CT_TBL_CHECK(name, cond) typedef char ct_tbl_check_##name[(cond) ? 1 : -1]',
    ...checkLines(hs),
    '',
    '/* Where each table holds pointers: the offsets inside one element (the type under every dimension). */',
    ...pointerLines(hs),
    '',
    ...descLines(hs),
    '',
    ...defineLines(hs),
    'const int ctTableDefineCount = (int)(sizeof ctTableDefines / sizeof ctTableDefines[0]);',
  ];
  return `${lines.join('\n')}\n`;
};

export { writeTablesStorage };
